#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Interchange

COMPONENT EnvironmentalSensor : 3
COMPONENT PointingDeviceSensor : 1
COMPONENT Scripting : 1
COMPONENT Sound : 3
COMPONENT Text : 2

PROTO MyClip [
  inputOutput SFTime   startTime 0
  inputOutput MFString url "media/tone48k-stereo.wav"
  inputOutput SFBool   loop TRUE
  inputOutput SFTime   stopTime 1
  outputOnly  SFBool   isActive
  outputOnly  SFTime   duration_changed
]
{
  AudioClip {
    url IS url
    loop IS loop
    startTime IS startTime
    stopTime IS stopTime
    isActive IS isActive
    duration_changed IS duration_changed
  }
}

Viewpoint {
  position 0 0 0
}

DEF SND Sound {
  location 3 0 0
  minBack 20
  minFront 20
  maxBack 40
  maxFront 40
  source DEF Q MyClip {
    startTime 946684800.048
  }
}

USE Q

DEF T TimeSensor {
  cycleInterval 0.5
  loop TRUE
}

DEF S Script {
  inputOnly      SFTime  set_time
  outputOnly     SFTime  start
  initializeOnly SFInt32 n 49

  url "javascript:
function set_time (value) { if (++ n === 12) start = value; }
"
}

DEF K Script {
  initializeOnly SFNode  s USE SND
  initializeOnly SFNode  q USE Q
  inputOnly      SFTime  set_time
  initializeOnly SFInt32 n 49

  url "javascript:
function set_time (value) { ++ n;
   if (n === 24) s.source = q;
}
"
  directOutput TRUE
}

ROUTE T.time TO S.set_time
ROUTE S.start TO Q.set_startTime
ROUTE T.time TO K.set_time
